-- 11 Days of Giving timeline LOCKED by Sean, 2026-11-19 ("lock the timeline"): join free by 11:59 PM Eastern Fri Dec 11 and you are
-- entered; winners drawn live one day at a time Dec 14 to 24; brands say yes by Fri Dec 4; providers done by Jan 15, 2027. Replaces the
-- Dec 1 to Jan 1 Countdown to Launch shape. The brand email stays a DRAFT until Sean approves it in HQ.
update ve_site_settings set value = value || jsonb_build_object('starts_on','2026-12-14','ends_on','2026-12-24','entry_closes','2026-12-11','fulfill_by','2027-01-15',
  'rules_locked_by','Sean, 2026-11-19 ("lock it", then "lock the timeline"; signed off in place of an attorney)') where key='giving_2026';
update ve_outreach_campaign_emails set subject = 'Present a day of our 11 Days of Giving, {business}?',
 body = E'Hi {first_name},\n\nVegans Explore opens January 1, and we are counting down with a free giveaway for the Vegan community. Everyone who joins free by December 11 is entered. Then, from December 14 to Christmas Eve, we draw winners live, one day at a time: the 11 Days of Giving.\n\nWe would like {business} to present one of those days. You give up to $150 in product: one item, a bundle, or a digital code. There is no fee, and nothing ships until a member wins. Then you ship within 7 business days, and you are done by January 15.\n\nYour prize goes up on our giveaway page now, linked to your Directory page, and helps people join before December 11. On your day you get a live draw with your prize, a co-branded post and story on our accounts, a mention in that day''s holiday email and your prize on the ads across Vegans Explore. You also get your own tracked link, and in January a report with your real numbers.\n\nWe are in our founding season, so this is a small-cost test: you decide on 2027 from the report.\n\nEverything is on one page, with a short form to save your day:\n{link}\n\nThe 11 days go first come, first served, and we need your yes by Friday, December 4.\n\nThank you,\nThe Vegans Explore team', updated_at = now()
 where campaign_slug='giving-2026-brands' and step=1;
update ve_campaign_programs set end_on='2026-12-04' where slug='giving-brands-2026';
